<?php $root=base_url('store/'.$settings->store_slug); ?>
<main class="sf-editorial"><a href="<?= $root; ?>">← Back to the store</a><p class="sf-editorial-kicker">Contact us</p><h1><?= htmlspecialchars($site_content['contact_heading']); ?></h1><p class="sf-editorial-intro"><?= nl2br(htmlspecialchars($site_content['contact_intro'])); ?></p><div class="sf-contact-grid"><section class="sf-contact-form" id="contact-form"><h2>Send a message</h2>
<?php if($contact_received): ?><p class="sf-contact-feedback" role="status">Thank you. Your message has reached our team. We’ll get back to you using the details you provided.</p><?php elseif($contact_can_submit): ?>
<?php if($contact_error): ?><p class="sf-contact-feedback error" role="alert"><?= htmlspecialchars($contact_error); ?></p><?php endif; ?>
<p>Leave a phone number or email address so we can reply.</p><form method="post" action="<?= $root.'/contact#contact-form'; ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name(); ?>" value="<?= $this->security->get_csrf_hash(); ?>"><input type="hidden" name="submission_ref" value="<?= htmlspecialchars($this->input->post('submission_ref') ?: $contact_key); ?>"><input type="hidden" name="product_id" value="<?= (int)($contact_product->id??0); ?>"><input name="website" tabindex="-1" autocomplete="off" hidden>
