<label>How can we help?<textarea name="message" rows="6" maxlength="4000" required><?= htmlspecialchars((string)($this->input->post('message')??'')); ?></textarea></label><button class="sf-feature-button primary">Send message ↗</button></form>
<?php else: ?><p>Please reach our team using the contact details alongside.</p><?php endif; ?></section><aside class="sf-contact-info"><h2>Visit & connect</h2><?php if(!empty($settings->store_address)): ?><address><?= htmlspecialchars($settings->store_address); ?></address><?php endif; ?><ul><?php if(!empty($settings->store_phone)): ?><li><a href="tel:<?= preg_replace('/[^+0-9]/','',$settings->store_phone); ?>"><?= htmlspecialchars($settings->store_phone); ?></a></li><?php endif; ?><?php if(!empty($settings->store_email)): ?><li><a href="mailto:<?= htmlspecialchars($settings->store_email); ?>"><?= htmlspecialchars($settings->store_email); ?></a></li><?php endif; ?></ul><h3>Working hours</h3><?php if($business_hours): ?><ul><?php foreach($business_hours as $line): ?><li><?= htmlspecialchars($line); ?></li><?php endforeach; ?></ul><?php else: ?><p>Contact the team to confirm opening hours before visiting.</p><?php endif; ?><?php if($public_branches): ?><h3>Our locations</h3><?php foreach($public_branches as $branch): ?><h4><?= htmlspecialchars($branch->warehouse_name); ?></h4><address><?= htmlspecialchars(trim(($branch->address??'')."\n".($branch->city??''))); ?></address><?php endforeach; ?><?php endif; ?></aside></div></main>
